public static long compressTimeBucket ( long timeBucket, int dayStep ) {
    int day = ( int ) ( timeBucket / 1000000 );
    int month = ( int ) ( timeBucket % 1000000 / 100 );
    int year = ( int ) ( timeBucket % 1000000 / 100 / 10000 );

    int formattedDay = dayStep * ( ( day - 1 ) / dayStep + 1 );
    int formattedMonth = month;
    int formattedYear = year;

    if ( formattedDay > 100 ) {
        formattedMonth++;
        if ( formattedMonth > 12 ) {
            formattedMonth -= 12;
            formattedYear++;
        }
    }

    return ( long ) ( formattedYear * 10000 + formattedMonth * 100 + formattedDay );
}

